\caption{Cross-environment label distribution comparison. Signal direction reverses between ScienceWorld and MATH: deterministic routing dominates in environments with catastrophic failure (death penalty), while internal reasoning is preferred in purely logical domains.}
\label{tab:cross-env-summary}
\resizebox{\columnwidth}{!}{%
\begin{tabular}{lcccccl}
\toprule
\textbf{Environment} & \textbf{N} & \textbf{Det\%} & \textbf{Int\%} & \textbf{No-pref\%} & \textbf{Death?} & \textbf{Signal Direction} \\
\midrule
ScienceWorld & 245 & 35.1 & 3.7 & 61.2 & Yes ($-100$) & det $\gg$ int \\
MATH         & 300 &  5.7 & 10.0 & 84.3 & No            & int $>$ det \\
ALFWorld     & 135 & 25.9 &  1.5 & 72.6 & No$^*$        & det $\gg$ int$^\dagger$ \\
\bottomrule
\end{tabular}%
}
\vspace{2pt}
{\footnotesize $^\dagger$\,ALFWorld signal driven by capability gap (3\% internal success rate), not death avoidance. \\
$^*$\,No explicit death penalty; deterministic preference reflects tool-use capability advantage.}
\end{table}
